const fs=require('fs'),path=require('path'),assert=require('assert/strict'),crypto=require('crypto'),{execFileSync}=require('child_process');
const root=path.resolve(__dirname,'..'),manifest=()=>require('../ROOM-01A_CHANGES.json');
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
function baselineText(file){let text=fs.readFileSync(path.join(root,file),'utf8').replaceAll('\r\n','\n');for(const p of [...(manifest().sourcePatches[file]||[])].reverse()){assert.equal(text.split(p.new).length,2,file+' unique ROOM-01A hunk');text=text.replace(p.new,()=>p.old);}return text;}
function validatePreservation(){const m=manifest();assert.equal(m.baselineCommit,'573d0e168ebc7de88a55f8589c3d37a7ca404693');assert.deepEqual(Object.keys(m.sourcePatches).sort(),['README.md','index.html','map-semantics.js','tests/fix01.cjs','tests/geo01-browser.cjs','tests/geo02-browser.cjs','tests/geo02-contract.cjs','tests/map01-browser.cjs'].sort());for(const [file,h] of Object.entries(m.baselineFiles)){const old=execFileSync('git',['show',m.baselineCommit+':'+file],{cwd:root,maxBuffer:2e6});assert.equal(hash(old),h.gitSha256);assert.equal(baselineText(file),old.toString().replaceAll('\r\n','\n'),file+' only approved ROOM-01A source hunks');if(!m.sourcePatches[file])assert.equal(hash(fs.readFileSync(path.join(root,file))),h.workingSha256,file+' exact protected working-tree bytes');}return {baseline:m.baselineCommit,protectedFiles:Object.keys(m.baselineFiles).length,changedFiles:Object.keys(m.sourcePatches)};}
module.exports={baselineText,validatePreservation};

